def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next(c for c in set(grid[0]) if c != 0)
    row_seps = [r for r in range(h) if all(v == sep for v in grid[r])]
    col_seps = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]

    def spans(n, separators):
        bounds = [-1] + separators + [n]
        return [(a + 1, b) for a, b in zip(bounds, bounds[1:]) if b > a + 1]

    row_tiles = spans(h, row_seps)
    col_tiles = spans(w, col_seps)

    # The palette is in the first tile of each tile row.
    colors = []
    for r0, r1 in row_tiles:
        colors.append(next(grid[r][c] for r in range(r0, r1)
                           for c in range(col_tiles[0][0], col_tiles[0][1])
                           if grid[r][c] not in (0, sep)))

    # Find the non-palette tile containing the pattern.
    pattern = None
    for ri, (r0, r1) in enumerate(row_tiles):
        for ci, (c0, c1) in enumerate(col_tiles[1:], 1):
            cells = [(r-r0, c-c0) for r in range(r0, r1)
                     for c in range(c0, c1) if grid[r][c] not in (0, sep)]
            if cells:
                pattern = cells
                break
        if pattern:
            break

    out = [row[:] for row in grid]
    for ri, (r0, r1) in enumerate(row_tiles):
        for c0, c1 in col_tiles:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = 0
            for dr, dc in pattern:
                out[r0 + dr][c0 + dc] = colors[ri]
    return out
